import in.aitechapp.telugumatalu.Transliterator;import java.util.*;import java.nio.file.*;import java.nio.charset.*;
public class EngineTest{
 static void eq(Object a,Object b){if(!a.equals(b))throw new AssertionError(a+" != "+b);}
 public static void main(String[]args)throws Exception{Map<String,String>w=new LinkedHashMap<>();for(String s:Files.readAllLines(Paths.get(args[0]),StandardCharsets.UTF_8)){String[]p=s.split("\t",2);if(p.length==2)w.put(p[0],p[1]);}Transliterator e=new Transliterator(w);eq(e.convert("ఏమండీ, ఎలా ఉన్నారు?"),"Emandi, ela unnaru?");eq(e.convert("రేపు meeting ఉంది. 10:30 కి call చేయండి 😊"),"Repu meeting undi. 10:30 ki call cheyandi 😊");eq(e.convert("శక్తి భక్తి క్షేత్రం"),"Shakti bhakti kshetram");eq(e.convert("౧౨౩"),"123");eq(e.convert("అమ్మ\nనాన్న"),"Amma\nNanna");e.natural=false;eq(e.convert("ఉన్నారు"),"Unnaaru");e.natural=true;e.custom.put("ఏమండీ","Dear Emaandi");eq(e.convert("ఏమండీ"),"Dear Emaandi");String text="ఏమండీ, ఎలా ఉన్నారు?\nరేపు meeting ఉంది 😊";String out=e.convert(text);for(Transliterator.Token t:e.align(text)){String converted=e.convert(text.substring(t.start,t.end));eq(out.substring(t.outStart,t.outEnd).toLowerCase(Locale.ROOT),converted.toLowerCase(Locale.ROOT));}for(int[]c:Transliterator.chunks(String.join(" ",Collections.nCopies(500,"అమ్మ")))){if(c[1]-c[0]>180)throw new AssertionError("chunk limit");}eq(e.convert("క్\u200dష"),"Ksha");for(Map.Entry<String,String>entry:w.entrySet()){e.capital=false;if(e.custom.containsKey(entry.getKey()))continue;eq(e.convert(entry.getKey()),entry.getValue());}System.out.println("Native engine: phrases, conjuncts, digits, custom spellings, alignment, chunking and "+w.size()+" word mappings passed");}
}
